import React from 'react';

import { ResolutionLabel } from './ResolutionLabel.js';
import { TooltipItem } from '../../../../types/tooltip.js';
import {
  StyledTitleContainer,
  StyledSeriesBasedContent,
  StyledChartTooltipHeader,
} from '../components/InteractiveChartTooltip.styles.js';
import { useInteractiveTooltip } from '../hooks/useInteractiveTooltip.js';

interface CategoricalTooltipHeaderProps {
  name: string;
  item?: TooltipItem;
  resolution?: string;
}

export const CategoricalTooltipHeader = ({
  name,
  item,
  resolution,
}: CategoricalTooltipHeaderProps) => {
  const { hasScrollbar } = useInteractiveTooltip();

  return (
    <StyledChartTooltipHeader data-testid="categorical-tooltip-header">
      <StyledTitleContainer gap={8}>
        <ResolutionLabel text={resolution} />
        {name}
      </StyledTitleContainer>
      {item && (
        <StyledSeriesBasedContent
          item={item}
          highlighted
          extraRightMargin={hasScrollbar}
        />
      )}
    </StyledChartTooltipHeader>
  );
};
